import "./GenerativeCollection.sol";
import "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";
import "@matterlabs/zksync-contracts/l2/system-contracts/Constants.sol";
import "@matterlabs/zksync-contracts/l2/system-contracts/libraries/SystemContractsCaller.sol";

/**
 * @title Collection Factory for ERC721 Tokens.
 */
contract CollectionFactory {
    address implementation;
    address generativeImplementation;
    bytes32 public proxyBytecodeHash;

    event OnlyOwnerCollectionCreated(address contractAddress, address owner, string collectionName, string symbol);
    event GenerativeCollectionCreated(address contractAddress, address owner, string collectionName, string symbol);

    /**
     * @dev Initializes the contract with the implementations for the collections.
     * @param _onlyOwnerImplementation Address of the OnlyOwner collection implementation.
     * @param _generativeImplementation Address of the Generative collection implementation.
     */
    constructor(address _onlyOwnerImplementation, address _generativeImplementation, bytes32 _proxyBytecodeHash) {
        implementation = _onlyOwnerImplementation;
        generativeImplementation = _generativeImplementation;
        proxyBytecodeHash = _proxyBytecodeHash;
    }

    /**
     * @dev Creates an OnlyOwner collection by cloning the provided implementation.
     * @param name The name of the new collection.
     * @param symbol The symbol of the new collection.
     */
    function createOnlyOwnerCollection(string memory name, string memory symbol) external {
        bytes memory initData = abi.encodeCall(
            OnlyOwnerCollection.initialize,
            (name, symbol)
        );

        bytes32 salt = keccak256(abi.encodePacked(msg.sender, name, symbol)); 

        (bool success, bytes memory returnData) = SystemContractsCaller
            .systemCallWithReturndata(
                uint32(gasleft()),
                address(DEPLOYER_SYSTEM_CONTRACT),
                uint128(0),
                abi.encodeCall(
                    DEPLOYER_SYSTEM_CONTRACT.create2,
                    (salt, proxyBytecodeHash, abi.encode(address(implementation), initData))
                )
            );

        require(success, "Deployment failed");
        address collectionAddress = abi.decode(returnData, (address));
        OnlyOwnerCollection(collectionAddress).transferOwnership(msg.sender);

        emit OnlyOwnerCollectionCreated(collectionAddress, msg.sender, name, symbol);
    }


    /**
     * @dev Creates a Generative collection by cloning the provided implementation.
     * @param metadata Metadata describing the properties of the collection.
     */
    function createGenerativeCollection(GenerativeCollectionMetadata calldata metadata, address feeRecipient) external {
        require(metadata.maxMint > 0, "Maximum mint cannot be 0");
        if (metadata.presaleStartTime > 0) {
            require(metadata.presaleMaxMint > 0, "Maximum mint cannot be 0");
        }

        // Use abi.encodeCall for initialization data
        bytes memory initData = abi.encodeCall(
            GenerativeCollection.initialize,
            (metadata, feeRecipient)
        );

        bytes32 salt = keccak256(abi.encodePacked(msg.sender, metadata.name, metadata.symbol));

        // Use abi.encodeCall for the system call data
        (bool success, bytes memory returnData) = SystemContractsCaller
            .systemCallWithReturndata(
                uint32(gasleft()),
                address(DEPLOYER_SYSTEM_CONTRACT),
                uint128(0),
                abi.encodeCall(
                    DEPLOYER_SYSTEM_CONTRACT.create2,
                    (salt, proxyBytecodeHash, abi.encode(address(generativeImplementation), initData))
                )
            );

        require(success, "Deployment failed");
        address collectionAddress = abi.decode(returnData, (address));
        GenerativeCollection(collectionAddress).transferOwnership(msg.sender);

        emit GenerativeCollectionCreated(collectionAddress, msg.sender, metadata.name, metadata.symbol);
    }
}


