/**
 * @title OnlyOwnerCollection
 * @dev An ERC721 contract which allows only the owner to mint new tokens.
 */
contract OnlyOwnerCollection is Initializable, UUPSUpgradeable, ERC721URIStorageUpgradeable, OwnableUpgradeable {

    /// @notice Emitted when a new token is minted.
    /// @param contractAddress The address of the contract where the token is minted.
    /// @param tokenURI The tokenURI of the minted token.
    event OnlyOwnerCollectionMint(address contractAddress, string tokenURI);

    /**
     * @dev Initializes the contract, setting the name, symbol
     * @param _name Name of the token.
     * @param _symbol Symbol of the token.
     */
    function initialize(string calldata _name, string calldata _symbol) initializer public {
        __UUPSUpgradeable_init();
        __Ownable_init();
        __ERC721_init(_name, _symbol);
    }

    /**
     * @dev Transfers the admin role of the UUPS proxy to a new address.
     * Can only be called by the current owner.
     * @param newAdmin The address to transfer the admin role to.
     */
    function transferProxyAdmin(address newAdmin) external onlyOwner {
        _changeAdmin(newAdmin);
    }

    using Counters for Counters.Counter;
    Counters.Counter private _tokenIds;

    function _authorizeUpgrade(address) internal override onlyOwner {}

    /**
     * @dev Mints a new NFT. Can only be called by the owner
     * @param recipient Address to receive the minted token.
     * @param tokenURI URI for the minted token.
     * @return uint256 Returns the ID of the minted token.
     */
    function mintNFT(address recipient, string memory tokenURI) public returns (uint256) {
        require(msg.sender == owner(), "Not owner or approved.");

